import assert from 'node:assert/strict';
import { ToyRoomStory } from '../src/js/toy-room/ToyRoomStory.js';
import { createToyRoomStoryContext } from '../src/js/toy-room/ToyRoomStoryContext.js';

const events = [];
const originalPlayer = { x: 280, y: 640, vx: 3, vy: 4, radius: 24, facing: 'right' };
const originalToy = { id: 'antigo', isOrganized: true };
const room = {
  ROOM_W: 1600, ROOM_H: 1200, canvas: { width: 640, height: 480 },
  cameraX: 0, cameraY: 0, player: originalPlayer, fairy: {},
  toys: [originalToy], furniture: [], tutorial: { active: false },
  introAlpha: 0, introBannerTimer: 0,
  touchState: { active: true, pointerId: 8, vectorX: 1, vectorY: 1 },
  keysDown: { KeyW: true }, actionBtnPressed: true,
  resolveCollisions: (x, y) => ({ x, y }),
  getCameraFrame: () => ({ x: 0, y: 0, zoom: 1 }),
  clearInput() { assert.equal(this, room); events.push('limpar'); }
};
const context = createToyRoomStoryContext(room);
const story = new ToyRoomStory(context);
assert.equal('room' in story, false, 'A narrativa não recebe nem retém a fase inteira.');
// Simula a troca de objetos feita por restore, mantendo o mesmo contrato.
room.player = { x: 900, y: 800, vx: 7, vy: 8, radius: 24, facing: 'left', isMoving: true };
room.fairy = { x: 1000, y: 700 };
room.toys = [{ id: 'novo', isOrganized: true, isCarried: false }];
room.furniture = [{ id: 'movel-atual' }];
room.audio = { playPickUpSound() { events.push('coleta'); }, setToyRoomMusicTrack(track) { events.push(track); } };
assert.equal(story.cameraTarget(), room.player, 'O alvo segue o jogador restaurado.');
assert.equal(context.actors.fairy, room.fairy);
assert.equal(context.exploration.toys, room.toys);
assert.equal(context.exploration.furniture, room.furniture);
room.cameraX = 300; room.canvas.width = 960;
assert.deepEqual(context.world.viewport(), { left: 300, top: 0, right: 1260, bottom: 480 });
context.exploration.returnToy(room.toys[0], { x: 1200, y: 900 });
assert.equal(room.organizedCount, 0);
assert.equal(originalToy.isOrganized, true, 'O brinquedo anterior permanece intocado.');
const carried = room.toys[0];
carried.isCarried = true; room.player.carriedItem = carried;
room.resolveCollisions = (x, y, radius) => {
  assert.deepEqual([x, y, radius], [900, 800, 32]);
  return { x: 880, y: 780 };
};
story.state.investigationStage = 'SEEKING_SWORD';
story.state.sword = { x: 900, y: 800, visible: true };
story.updateAfterMovement();
assert.equal(story.state.investigationStage, 'PICKUP');
assert.equal(room.player.carriedItem, null);
assert.deepEqual([carried.x, carried.y, carried.isCarried], [880, 780, false]);
assert.deepEqual(events, ['limpar', 'coleta', 'sword'], 'A limpeza e o áudio conservam sua ordem.');
assert.deepEqual([room.player.vx, room.player.vy, room.player.isMoving], [0, 0, false]);
assert.deepEqual([originalPlayer.vx, originalPlayer.vy], [3, 4], 'A limpeza usa somente o jogador atual.');
assert.equal(room.touchState.active, false);
assert.deepEqual(room.keysDown, {});
assert.equal(room.actionBtnPressed, false);
story.state.swordEquipped = true;
assert.equal(story.attack(), true);
assert.equal(story.state.attackDirection, -1, 'O ataque usa a direção do jogador restaurado.');
assert.deepEqual(Object.keys(story.snapshot()).sort(), Object.keys(story.state).sort(), 'O contrato não entra no save.');
console.log('APROVADO: contrato sem acesso à fase completa, referências atuais, identidade dos itens, câmera, soltura, controles, ordem de áudio e snapshot narrativo.');
